1	import rows from "./prices.json";
2	
3	// Prices are USD per 1M tokens, taken from src/price/prices.json.
4	// A null price means "not confirmed", so a session that uses it has a null cost. We never guess.
5	
6	export type PriceRow = {
7	  id: string;
8	  model_pattern: string;
9	  input: number | null;
10	  output: number | null;
11	  cache_read: number | null;
12	  cache_write: number | null;
13	  cache_write_1h?: number | null;
14	  max_prompt_tokens?: number;
15	  min_prompt_tokens?: number;
16	  source_url: string | null;
17	  checked_on: string;
18	};
19	
20	export type TokenCounts = {
21	  /** Uncached input tokens. For OpenAI-style usage, subtract cached_input_tokens first. */
22	  input: number;
23	  /** Output tokens. For OpenAI-style usage, add reasoning_output_tokens (billed as output). */
24	  output: number;
25	  cache_read?: number;
26	  /** 5-minute cache writes. */
27	  cache_write?: number;
28	  /** 1-hour cache writes. Only priced where the row has cache_write_1h. */
29	  cache_write_1h?: number;
30	  /**
31	   * Total input of one request: input + cache_read + cache_write + cache_write_1h.
32	   * Tiered rows (Haiku 5.5 above 100k tokens) need it, so pass a single request's counts.
33	   * Sum the per-request results for a session.
34	   */
35	  prompt_tokens?: number;
36	  /**
37	   * Upper bound on any one request's prompt size, for when per-request sizes are not stored (a session's
38	   * total input is at least as large as any single request in it). Used only when it selects one tier;
39	   * otherwise the tier is unknown and the result is the short-tier price flagged as a lower bound.
40	   */
41	  prompt_tokens_bound?: number;
42	};
43	
44	export type PriceResult = {
45	  usd: number | null;
46	  row_id: string;
47	  /** "assumed-short": the prompt size was unknown, so the base (short-context) row was used. It may understate. */
48	  tier?: "assumed-short";
49	  /** True with tier "assumed-short": the real cost is at least usd (the long tier costs more per token). */
50	  lower_bound?: true;
51	};
52	
53	const ROWS = rows.rows as PriceRow[];
54	
55	// Bedrock regional and multi-region endpoints cost 10% more than global ones
56	// (platform.claude.com/docs/en/about-claude/pricing, "Regional and multi-region endpoint pricing").
57	const REGIONAL_PREFIXES = new Set(["us", "eu", "jp", "au", "apac"]);
58	const REGIONAL_PREMIUM = 1.1;
59	
60	/**
61	 * Reduces a model id to its base name, e.g.
62	 *   "us.anthropic.claude-opus-5-5-v1:0" -> { base: "claude-opus-5-5", regional: true }
63	 *   "claude-opus-5-5[1m]"               -> { base: "claude-opus-5-5", regional: false }
64	 *   "global.anthropic.claude-haiku-5-5" -> { base: "claude-haiku-5-5", regional: false }
65	 *   "claude-sonnet-5-5-20260601"        -> { base: "claude-sonnet-5-5", regional: false }
66	 */
67	export function normaliseModelId(model: string): { base: string; regional: boolean } {
68	  let id = model.trim().toLowerCase();
69	  id = id.replace(/\[[^\]]*\]$/, "");
70	  let regional = false;
71	  for (;;) {
72	    const m = id.match(/^([a-z]+)\./);
73	    if (!m) break;
74	    const prefix = m[1] ?? "";
75	    if (prefix === "global") regional = false;
76	    else if (REGIONAL_PREFIXES.has(prefix)) regional = true;
77	    else if (prefix !== "anthropic") break;
78	    id = id.slice(m[0].length);
79	  }
80	  id = id.replace(/-v\d+(:\d+)?$/, "");
81	  id = id.replace(/-\d{8}$/, "").replace(/-\d{4}-\d{2}-\d{2}$/, "");
82	  return { base: id, regional };
83	}
84	
85	function pickRow(
86	  base: string,
87	  promptTokens: number | undefined,
88	  bound: number | undefined,
89	): PriceRow | "assumed-short" | undefined {
90	  const candidates = ROWS.filter((r) => r.model_pattern === base);
91	  if (candidates.length === 0) return undefined;
92	  if (candidates.length === 1) return candidates[0];
93	  if (promptTokens === undefined) {
94	    // prices.json documents no rule for an unknown prompt size, so fall back to the base (short-context) row.
95	    if (bound === undefined) return "assumed-short";
96	    // A row is reachable when its range starts at or below the bound. Only one reachable row is certain.
97	    const reachable = candidates.filter((r) => r.min_prompt_tokens === undefined || r.min_prompt_tokens <= bound);
98	    return reachable.length === 1 ? reachable[0] : "assumed-short";
99	  }
100	  return candidates.find(
101	    (r) =>
102	      (r.max_prompt_tokens === undefined || promptTokens <= r.max_prompt_tokens) &&
103	      (r.min_prompt_tokens === undefined || promptTokens >= r.min_prompt_tokens),
104	  );
105	}
106	
107	/** Prices one token-count record for a model. Returns usd: null when the model or price is unknown. */
108	export function priceSession(model: string, tokens: TokenCounts): PriceResult {
109	  const { base, regional } = normaliseModelId(model);
110	  const picked = pickRow(base, tokens.prompt_tokens, tokens.prompt_tokens_bound);
111	  if (picked === undefined) return { usd: null, row_id: "unknown" };
112	  const assumed = picked === "assumed-short";
113	  const row = assumed ? ROWS.find((r) => r.model_pattern === base && r.min_prompt_tokens === undefined) : picked;
114	  if (row === undefined) return { usd: null, row_id: "unknown" };
115	  const tier = assumed ? ({ tier: "assumed-short", lower_bound: true } as const) : {};
116	
117	  const counts: [number, number | null | undefined][] = [
118	    [tokens.input, row.input],
119	    [tokens.output, row.output],
120	    [tokens.cache_read ?? 0, row.cache_read],
121	    [tokens.cache_write ?? 0, row.cache_write],
122	    [tokens.cache_write_1h ?? 0, row.cache_write_1h],
123	  ];
124	  let usd = 0;
125	  for (const [count, price] of counts) {
126	    if (count === 0) continue;
127	    if (price === null || price === undefined) return { usd: null, row_id: row.id, ...tier };
128	    usd += (count * price) / 1_000_000;
129	  }
130	  return { usd: regional ? usd * REGIONAL_PREMIUM : usd, row_id: row.id, ...tier };
131	}
