1	// DeepSeek time-of-day pricing (DESIGN.md §"Candidate generation").
2	// Source: https://api-docs.deepseek.com/quick_start/pricing
3	//
4	// Peak is 01:00–04:00 and 06:00–10:00 UTC, Monday through Friday. Every other hour is off-peak, weekends
5	// included. Off-peak is half the peak rate. The rows hold the PEAK rates:
6	//   input = cache miss, cache_read = cache hit, output = output.
7	// The page also excludes Chinese public holidays from peak. We keep no holiday calendar, so a holiday is
8	// priced at peak. That overstates its cost and never understates it.
9	//
10	// These rows live here, not in src/price/prices.json. priceSession() reads prices.json with no time-of-day
11	// rule, so a DeepSeek row there would bill off-peak runs at the peak rate.
12	
13	import type { TokenCounts } from "./index.ts";
14	
15	export const OFF_PEAK_FACTOR = 0.5;
16	
17	export interface DeepSeekRow {
18	  id: string;
19	  model_pattern: string;
20	  /** Peak USD per 1M tokens. */
21	  input: number;
22	  output: number;
23	  cache_read: number;
24	  cache_write: null;
25	  source_url: string;
26	  checked_on: string;
27	}
28	
29	const SOURCE_URL = "https://api-docs.deepseek.com/quick_start/pricing";
30	const CHECKED_ON = "2026-10-10";
31	
32	export const DEEPSEEK_ROWS: DeepSeekRow[] = [
33	  {
34	    id: "deepseek-flash",
35	    model_pattern: "deepseek-flash",
36	    input: 0.3,
37	    output: 1.2,
38	    cache_read: 0.006,
39	    cache_write: null,
40	    source_url: SOURCE_URL,
41	    checked_on: CHECKED_ON,
42	  },
43	  {
44	    id: "deepseek-v4-pro",
45	    model_pattern: "deepseek-v4-pro",
46	    input: 1.32,
47	    output: 3.96,
48	    cache_read: 0.044,
49	    cache_write: null,
50	    source_url: SOURCE_URL,
51	    checked_on: CHECKED_ON,
52	  },
53	];
54	
55	export type DeepSeekPrice = {
56	  /** null when a counted token type has no confirmed price. */
57	  usd: number | null;
58	  row_id: string;
59	  peak: boolean;
60	};
61	
62	/** True during DeepSeek's peak window, judged in UTC. The end hour is exclusive: 04:00 and 10:00 are off-peak. */
63	export function isPeak(at: Date): boolean {
64	  const day = at.getUTCDay();
65	  if (day === 0 || day === 6) return false;
66	  const h = at.getUTCHours();
67	  return (h >= 1 && h < 4) || (h >= 6 && h < 10);
68	}
69	
70	/**
71	 * Prices one token-count record for a DeepSeek model at a given instant.
72	 * Returns null for a model that is not a DeepSeek row. Returns usd: null when a counted token type has no price.
73	 */
74	export function priceDeepSeek(model: string, tokens: TokenCounts, at: Date): DeepSeekPrice | null {
75	  const row = DEEPSEEK_ROWS.find((r) => r.model_pattern === model.trim().toLowerCase());
76	  if (row === undefined) return null;
77	
78	  const peak = isPeak(at);
79	  const factor = peak ? 1 : OFF_PEAK_FACTOR;
80	  const counts: [number, number | null | undefined][] = [
81	    [tokens.input, row.input],
82	    [tokens.output, row.output],
83	    [tokens.cache_read ?? 0, row.cache_read],
84	    [tokens.cache_write ?? 0, row.cache_write],
85	  ];
86	  let usd = 0;
87	  for (const [count, price] of counts) {
88	    if (count === 0) continue;
89	    if (price === null || price === undefined) return { usd: null, row_id: row.id, peak };
90	    usd += (count * price) / 1_000_000;
91	  }
92	  return { usd: usd * factor, row_id: row.id, peak };
93	}
