28	function git(repo: string, args: string[]): { ok: boolean; out: string } {
29	  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
30	  return { ok: p.exitCode === 0, out: p.stdout.toString().trim() };
31	}
