33	function commitTimeMs(repo: string, rev: string): number {
34	  return Number(git(repo, ["log", "-1", "--format=%ct", rev]).out) * 1000;
35	}
36	
37	/** Why `sha` is not mature against HEAD, or null when it is. */
38	export function maturity(repo: string, sha: string): Censor | null {
39	  if (!git(repo, ["merge-base", "--is-ancestor", sha, "HEAD"]).ok) return "not_on_head";
40	  const newer = Number(git(repo, ["rev-list", "--first-parent", "--count", `${sha}..HEAD`]).out);
41	  const age = commitTimeMs(repo, "HEAD") - commitTimeMs(repo, sha);
42	  return newer >= MATURE_MIN_COMMITS && age >= MATURE_MIN_AGE_MS ? null : "too_young";
43	}
